with me as (select id from auth.users order by created_at limit 1)
insert into public.stories (user_id, date, data) select id, '2026-10-25', '{"createdAt": 1792889703157, "date": "2026-10-25", "kanjiKnown": 40, "level": 2, "sentences": [{"en": "Today is October 25th.", "jp": "{今日|きょう}は{十月|じゅうがつ}にじゅうごにちです。"}, {"en": "I went to a big park.", "jp": "{大|おお}きい{公園|こうえん}に{行|い}きました。"}, {"en": "There were many people in the park.", "jp": "{公園|こうえん}の{中|なか}に{人々|ひとびと}がたくさんいました。"}, {"en": "A girl is playing with three balls.", "jp": "{女|おんな}の{子|こ}が{三|みっ}つのボールで{遊|あそ}んでいます。"}, {"en": "A boy climbs up a mountain-shaped slide.", "jp": "{男|おとこ}の{子|こ}は{山|やま}の{形|かたち}のすべり{台|だい}に{上|のぼ}ります。"}, {"en": "When he got to the top, he laughed in a loud voice.", "jp": "{上|うえ}まで{上|あが}ると、{大|おお}きいこえで{笑|わら}いました。"}, {"en": "I took out a rice ball under a tree.", "jp": "わたしは{木|き}の{下|した}でおにぎりを{出|だ}しました。"}, {"en": "A small dog is sleeping under the same tree.", "jp": "{同|おな}じ{木|き}の{下|した}で、{小|ちい}さい{犬|いぬ}がねています。"}, {"en": "The sun is out, and it feels nice.", "jp": "{日|ひ}ざしがあって、{気持|きも}ちがいいです。"}, {"en": "Five minutes later, my friend came.", "jp": "{五|ご}{分|ふん}あとに、{友|とも}だちが{来|き}ました。"}, {"en": "We shared the rice ball and ate it together.", "jp": "いっしょにおにぎりを{分|わ}けて{食|た}べました。"}, {"en": "Forgetting my busy daily life, it was a good day.", "jp": "{日々|ひび}のいそがしさをわすれて、いい{一日|いちにち}でした。"}], "title": "{日曜日|にちようび}の{公園|こうえん}", "titleEn": "Sunday at the Park", "words": [{"meaning": "park", "reading": "こうえん", "word": "公園"}, {"meaning": "to play", "reading": "あそぶ", "word": "遊ぶ"}, {"meaning": "to laugh", "reading": "わらう", "word": "笑う"}, {"meaning": "tree", "reading": "き", "word": "木"}, {"meaning": "dog", "reading": "いぬ", "word": "犬"}, {"meaning": "friend", "reading": "ともだち", "word": "友だち"}, {"meaning": "feeling", "reading": "きもち", "word": "気持ち"}, {"meaning": "to eat", "reading": "たべる", "word": "食べる"}], "wordsKnown": 25}'::jsonb from me
